public static int countOilDeposits(char[][] grid) {
    Set<Integer> deposits = new HashSet<>();
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                // Check if the current '@' has been visited before
                if (!deposits.contains(i * grid[i].length + j)) {
                    // If not, start a new BFS search to find all the connected '@'
                    bfsSearch(grid, i, j, deposits);
                }
            }
        }
    }
    return deposits.size();
}

private static void bfsSearch(char[][] grid, int i, int j, Set<Integer> deposits) {
    Queue<Integer> queue = new LinkedList<>();
    queue.add(i * grid[i].length + j);
    deposits.add(i * grid[i].length + j);
    while (!queue.isEmpty()) {
        int currentCell = queue.poll();
        int currentRow = currentCell / grid[i].length;
        int currentCol = currentCell % grid[i].length;
        for (int k = -1; k <= 1; k++) {
            for (int l = -1; l <= 1; l++) {
                int neighborRow = currentRow + k;
                int neighborCol = currentCol + l;
                if (neighborRow >= 0 && neighborRow < grid.length && neighborCol >= 0 && neighborCol < grid[i].length
                        && grid[neighborRow][neighborCol] == '@') {
                    int neighborCell = neighborRow * grid[i].length + neighborCol;
                    if (!deposits.contains(neighborCell)) {
                        queue.add(neighborCell);
                        deposits.add(neighborCell);
                    }
                }
            }
        }
    }
}

