public static int maxRegions(int N) {
    // Base case: N = 0, there are no triangles, so there are no regions
    if (N == 0) {
        return 0;
    }

    // Base case: N = 1, there is one triangle, so there are two regions
    if (N == 1) {
        return 2;
    }

    // Recursive case: N > 1, there are at least two triangles
    int regions = 2; // start with two regions (the two triangles)
    for (int i = 2; i <= N; i++) {
        regions += maxRegions(i - 1); // recursively calculate the maximum number of regions for the smaller problem
    }
    return regions;
}

