    Stack<Integer> stack = new Stack<>();
    stack.push(start[0]);
    visited[start[0]] = true;

    while (!stack.isEmpty()) {
        int current = stack.pop();
        if (current == end[0]) {
            return "can be travelled";
        }
        for (int neighbor : paths[current]) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                stack.push(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // initialize variables
    boolean[][] visited = new boolean[n][n];
    boolean[][] walls = new boolean[n][n];
    int[][] dist = new int[n][n];

    // initialize distances and walls
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            dist[i][j] = Integer.MAX_VALUE;
            walls[i][j] = true;
        }
    }

    // mark the starting n-tersection as visited and set its distance to 0
    visited[start[0]][start[1]] = true;
    dist[start[0]][start[1]] = 0;

    // perform BFS
    Queue<Node> queue = new LinkedList<>();
    queue.add(new Node(start[0], start[1], 0));

    while (!queue.isEmpty()) {
        Node node = queue.poll();
        int i = node.x;
        int j = node.y;
        int d = node.d;

        // if the current n-tersection is the ending n-tersection, return "can be travelled"
        if (i == end[0] && j == end[1]) {
            return "can be travelled";
        }

        // if the current n-tersection is not visited, mark it as visited and set its distance to the minimum distance
        if (!visited[i][j]) {
            visited[i][j] = true;
            dist[i][j] = d;
        }

        // add the neighbors of the current n-tersection to the queue
        for (int k = 0; k < paths.length; k++) {
            int ni = i + directions[k][0];
            int nj = j + directions[k][1];

            if (ni >= 0 && ni < n && nj >= 0 && nj < n && !visited[ni][nj]) {
                visited[ni][nj] = true;
                dist[ni][nj] = d + 1;
                queue.add(new Node(ni, nj, d + 1));
            }
        }
    }

    // if the ending n-tersection was not reached during the BFS, return "cannot be travelled"
    if (dist[end[0]][end[1]] == Integer.MAX_VALUE) {
        return "cannot be travelled";
    }

    // return "can be travelled"
    return "can be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    //Check if the starting and ending n-tersections are in the valid range
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n ||
            end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    //Check if the start and end n-tersections are not the same n-tersection
    if (start[0] == end[0] && start[1] == end[1]) {
        return "cannot be travelled";
    }

    //Check if there is a path between the starting and ending n-tersections
    int pathsLength = paths.length;
    for (int i = 0; i < pathsLength; i++) {
        int[] path = paths[i];
        if ((path[0] == start[0] && path[1] == start[1]) ||
                (path[2] == end[0] && path[3] == end[1])) {
            return "can be travelled";
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Handle edge cases
  if (n <= 0 || start.length != end.length || paths.length == 0) {
    return "cannot be travelled";
  }

  // Initialize variables
  int numPaths = paths.length;
  boolean[] visited = new boolean[n];
  Queue<int[]> queue = new LinkedList<>();

  // Enqueue starting n-tersection and mark as visited
  visited[start] = true;
  queue.add(start);

  // Perform BFS search
  while (!queue.isEmpty()) {
    int[] curr = queue.poll();
    int x = curr[0];
    int y = curr[1];

    for (int i = 0; i < numPaths; i++) {
      int[] next = paths[i];
      int x2 = next[0];
      int y2 = next[1];

      // If next n-tersection is not visited and is not the starting n-tersection
      if (!visited[x2][y2] && x2 != start[0] && y2 != start[1]) {
        visited[x2][y2] = true;
        queue.add(next);
      }
    }
  }

  // Check if ending n-tersection is visited
  if (visited[end[0]][end[1]]) {
    return "can be travelled";
  } else {
    return "cannot be travelled";
  }
}

public static String appx(String word1, String word2) {
    // Validate inputs
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input words cannot be null");
    }

    // Initialize variables
    int commonLetters = 0;
    int word1Len = word1.length();
    int word2Len = word2.length();
    int totalLetters = word1Len + word2Len;

    // Count common letters
    for (int i = 0; i < word1Len; i++) {
        for (int j = 0; j < word2Len; j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }

    // Return reduced fraction
    return "appx(" + word1 + ", " + word2 + ") = " + commonLetters + "/" + totalLetters;
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Invalid input: Both words must be non-null");
    }

    int commonChars = 0;
    for (int i = 0; i < Math.min(word1.length(), word2.length()); i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonChars++;
        }
    }

    int divisor = word1.length() + word2.length();
    int reducedNumerator = commonChars;
    int reducedDenominator = divisor;

    while (reducedNumerator > 1 && reducedDenominator > 1) {
        if (reducedNumerator > reducedDenominator) {
            reducedNumerator -= reducedDenominator;
        } else {
            reducedDenominator -= reducedNumerator;
        }
    }

    return "appx(" + word1 + ", " + word2 + ") = " + reducedNumerator + "/" + reducedDenominator;
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("words cannot be null");
    }
    int commonLetters = 0;
    for (char c : word1.toCharArray()) {
        if (word2.contains(String.valueOf(c))) {
            commonLetters++;
        }
    }
    int word1Length = word1.length();
    int word2Length = word2.length();
    int denominator = word1Length + word2Length - commonLetters;
    if (denominator == 0) {
        return "0";
    }
    int numerator = commonLetters;
    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;
    return String.format("%d/%d", numerator, denominator);
}

