    if (!date.matches("\\d{2} \\d{2} \\d{4}")) {
        throw new IllegalArgumentException("Invalid date format");
    }

    // Get the day of the week from the date
    int dayOfWeek = getDayOfWeek(date);

    // Get the name of the weekday from the day of the week
    String weekday = getWeekday(dayOfWeek);

    // Return the date in the format "MMMM dd, yyyy is a weekday"
    return String.format("%s is a %s", date, weekday);
}

public static int getDayOfWeek(String date) {
    // Split the date into its parts
    String[] parts = date.split(" ");
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    // Calculate the day of the week using the Zeller's congruence formula
    return (day + (2.6 * month - 0.2) - 2 * (year / 100) + (year / 100) / 4 + 5 * (year / 100)) % 7;
}

public static String getWeekday(int dayOfWeek) {
    switch (dayOfWeek) {
        case 0:
            return "Sunday";
        case 1:
            return "Monday";
        case 2:
            return "Tuesday";
        case 3:
            return "Wednesday";
        case 4:
            return "Thursday";
        case 5:
            return "Friday";
        case 6:
            return "Saturday";
        default:
            throw new IllegalArgumentException("Invalid day of week");
    }
}

