public int search(int[] nums, int target) {
    int left = 0;
    int right = nums.length - 1;

    while (left <= right) {
        int mid = (left + right) / 2;
        if (nums[mid] == target) {
            return mid;
        }

        if (nums[mid] >= nums[left]) {
            if (target >= nums[left] && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            if (target <= nums[right] && target > nums[mid]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    return -1;
}

public int search(int[] nums, int target) {
    int left = 0;
    int right = nums.length - 1;
    int mid;
    boolean found = false;

    // Traverse the array
    while (left <= right) {
        mid = (left + right) / 2;

        // Check if the target is at the midpoint
        if (nums[mid] == target) {
            found = true;
            break;
        }

        // Check if the array is rotated at midpoint
        if (nums[mid] > nums[right]) {
            // If the array is rotated, check if the target is in the left half
            if (target < nums[mid] && target >= nums[left]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            // If the array is not rotated, check if the target is in the right half
            if (target > nums[mid] && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    if (found) {
        return mid;
    } else {
        return -1;
    }
}

public static int search(int[] nums, int target) {
        // Check if the array is empty or the target value is outside the range
        if (nums.length == 0 || target < nums[0] || target > nums[nums.length - 1]) {
            return -1;
        }

        // Find the pivot index where the array is rotated
        int pivot = findPivot(nums, 0, nums.length - 1);

        // Search for the target value in the left and right subarrays
        int left = search(nums, target, 0, pivot - 1);
        int right = search(nums, target, pivot, nums.length - 1);

        // Return the index of the target value if found, or -1 otherwise
        return (left != -1) ? left : right;
    }

private static int search(int[] nums, int target, int low, int high) {
        if (low == high) {
            return nums[low] == target ? low : -1;
        }

        int mid = (low + high) / 2;

        // If the mid value is less than or equal to the target, search the right subarray
        if (nums[mid] <= target) {
            return search(nums, target, mid + 1, high);
        }

        // If the mid value is greater than the target, search the left subarray
        return search(nums, target, low, mid - 1);
    }

private static int findPivot(int[] nums, int low, int high) {
        if (low == high) {
            return low;
        }

        int mid = (low + high) / 2;

        // If the mid value is less than or equal to the last value, the pivot is in the left subarray
        if (nums[mid] <= nums[high]) {
            return findPivot(nums, low, mid);
        }

        // If the mid value is greater than the last value, the pivot is in the right subarray
        return findPivot(nums, mid + 1, high);
    }

