}

public static double trimMean(int[] arr) {
    // Check if the input array is valid
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Input array cannot be null or empty");
    }

    // Calculate the mean of the array
    double mean = calculateMean(arr);

    // Calculate the trimmed mean using the given parameters
    double trimmedMean = calculateTrimmedMean(arr, 0.05, 0.05);

    // Return the trimmed mean
    return trimmedMean;
}

private static double calculateMean(int[] arr) {
    double sum = 0.0;
    for (int i = 0; i < arr.length; i++) {
        sum += arr[i];
    }
    return sum / arr.length;
}

private static double calculateTrimmedMean(int[] arr, double lowerPercentile, double upperPercentile) {
    // Check if the percentiles are valid
    if (lowerPercentile < 0 || lowerPercentile > 1 || upperPercentile < 0 || upperPercentile > 1) {
        throw new IllegalArgumentException("Percentiles must be between 0 and 1");
    }

    // Calculate the number of elements to remove from the lower and upper ends of the array
    int lowerElementsToRemove = (int) Math.ceil(lowerPercentile * arr.length);
    int upperElementsToRemove = (int) Math.ceil(upperPercentile * arr.length);

    // Remove the elements from the lower and upper ends of the array
    int[] trimmedArr = arr.clone();
    if (lowerElementsToRemove > 0) {
        trimmedArr = Arrays.copyOfRange(trimmedArr, lowerElementsToRemove, trimmedArr.length - upperElementsToRemove);
    }

    // Calculate the mean of the trimmed array
    double trimmedMean = calculateMean(trimmedArr);

    // Return the trimmed mean
    return trimmedMean;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Input array cannot be null or empty");
    }

    // Calculate the mean of the input array
    double mean = 0;
    for (int i = 0; i < arr.length; i++) {
        mean += arr[i];
    }
    mean /= arr.length;

    // Calculate the trimmed mean
    double trimMean = 0;
    int n = arr.length;
    int trimCount = (int) Math.round(n * 0.05);
    for (int i = trimCount; i < n - trimCount; i++) {
        trimMean += arr[i];
    }
    trimMean /= n - 2 * trimCount;

    return trimMean;
}

public static double trimMean(int[] arr) {
    // Calculate the mean of the remaining elements after removing the smallest 5% and largest 5% of the elements
    if (arr.length < 10) {
        throw new IllegalArgumentException("The length of the input array must be at least 10");
    }
    int n = arr.length;
    int[] sortedArr = Arrays.copyOf(arr, n);
    Arrays.sort(sortedArr);
    int startIndex = (int) Math.floor((n - 5) / 100.0);
    int endIndex = (int) Math.ceil((n - 5) / 100.0);
    double sum = 0.0;
    double count = 0.0;
    for (int i = startIndex; i < endIndex; i++) {
        sum += sortedArr[i];
        count++;
    }
    return sum / count;
}

