    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the trimmed mean
    int trim = (int) Math.round(arr.length * 0.05);
    double trimMean = 0.0;
    for (int i = trim; i < arr.length - trim; i++) {
        trimMean += arr[i];
    }
    trimMean /= (arr.length - 2 * trim);

