    // Calculate the mean
    return sum / (n - 2 * n5);
}

public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) {
        return false;
    }
    int n = arr.length / 2;
    int[] pairs = new int[n];
    for (int i = 0; i < n; i++) {
        pairs[i] = arr[i] + arr[n + i];
    }
    for (int i = 0; i < n; i++) {
        if (pairs[i] % k != 0) {
            return false;
        }
    }
    return true;
}

