        int right = k - left;
        if (left == right) {
            pairs[i] = left;
            used[i] = true;
        } else {
            for (int j = i + 1; j < arr.length; j++) {
                if (!used[j] && arr[j] == right) {
                    pairs[i] = left;
                    pairs[j] = right;
                    used[i] = true;
                    used[j] = true;
                    break;
                }
            }
        }
    }
    for (int i = 0; i < pairs.length; i++) {
        if (pairs[i] == 0) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    int[] sums = new int[n/2];
    for (int i = 0; i < n/2; i++) {
        sums[i] = arr[2*i] + arr[2*i+1];
    }
    for (int i = 0; i < n/2; i++) {
        if (sums[i] % k != 0) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) {
        return false;
    }
    int pairs = arr.length / 2;
    for (int i = 0; i < pairs; i++) {
        int sum = arr[i] + arr[arr.length - i - 1];
        if (sum % k != 0) {
            return false;
        }
    }
    return true;
}

String minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a HashMap to store the time required to reach each node
    HashMap<Integer, Integer> timeMap = new HashMap<>();

    // Initialize a Queue to perform BFS
    Queue<Integer> queue = new LinkedList<>();

    // Mark node 0 as visited and set the time required to reach it to 0
    timeMap.put(0, 0);
    queue.add(0);

    while (!queue.isEmpty()) {
        int current = queue.remove();
        int currentTime = timeMap.get(current);
        for (int neighbor : edges[current]) {
            if (!timeMap.containsKey(neighbor)) {
                timeMap.put(neighbor, currentTime + 1);
                queue.add(neighbor);
            }
            if (hasApple[neighbor]) {
                return (currentTime + 1) + " " + neighbor;
            }
        }
    }

    return "0";
}

public static int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the minimum time required to collect all apples
    int minTime = 0;

    // Create a boolean array to keep track of visited nodes
    boolean[] visited = new boolean[n];

    // Perform DFS to find the shortest path
    dfs(0, edges, visited, hasApple, minTime);

    // Return the minimum time required to collect all apples
    return minTime;
}

private static void dfs(int node, int[][] edges, boolean[] visited, boolean[] hasApple, int minTime) {
    // Mark the current node as visited
    visited[node] = true;

    // Traverse all the neighboring nodes that have not been visited before
    for (int i = 0; i < edges.length; i++) {
        int nextNode = edges[i][0];
        if (!visited[nextNode]) {
            // Update the minimum time required to collect all apples
            if (hasApple[nextNode]) {
                minTime = Math.max(minTime, edges[i][1] + 1);
            }
            // Recursively call the DFS function for the neighboring node
            dfs(nextNode, edges, visited, hasApple, minTime);
        }
    }
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Initialize the minimum time required to collect all apples and return to node 0
  int minTime = 0;

  // Initialize a boolean array to keep track of visited nodes
  boolean[] visited = new boolean[n];

  // Initialize a queue to perform BFS
  Queue<Integer> queue = new LinkedList<>();

  // Mark the starting node as visited and add it to the queue
  visited[0] = true;
  queue.add(0);

  // Perform BFS
  while (!queue.isEmpty()) {
    int node = queue.poll();

    // For each edge connected to the current node, check if the destination node has an apple
    for (int i = 0; i < edges[node].length; i++) {
      int destination = edges[node][i];
      if (hasApple[destination]) {
        // If the destination node has an apple, mark it as visited and add it to the queue
        visited[destination] = true;
        queue.add(destination);

        // Increment the minimum time required to collect all apples and return to node 0
        minTime++;
      }
    }
  }

  // Return the total minimum time required to collect all apples and return to node 0
  return minTime;
}

