    // Create a graph with n nodes and edges
    Graph graph = new Graph(n);
    for (int[] edge : edges) {
        graph.addEdge(edge[0], edge[1]);
    }

    // Initialize the minimum time required to collect all the apples
    int minTime = 0;

    // Perform a depth-first search (DFS) on the graph
    dfs(graph, 0, hasApple, minTime);

    return minTime;
}

private int dfs(Graph graph, int node, boolean[] hasApple, int currentTime) {
    // If the current node has an apple, add the time required to collect it
    if (hasApple[node]) {
        currentTime += 2;
    }

    // Recursively visit all child nodes
    for (int child : graph.getChildren(node)) {
        currentTime = dfs(graph, child, hasApple, currentTime);
    }

    // Update the minimum time required to collect all the apples
    minTime = Math.min(minTime, currentTime);

    return currentTime;
}

