public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        int minIndex = 0;
        int maxIndex = s.length() - 1;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < s.charAt(minIndex)) {
                minIndex = i;
            }
            if (s.charAt(i) > s.charAt(maxIndex)) {
                maxIndex = i;
            }
        }
        result.append(s.charAt(minIndex));
        result.append(s.charAt(maxIndex));
        s = s.substring(0, minIndex) + s.substring(minIndex + 1);
        s = s.substring(0, maxIndex) + s.substring(maxIndex + 1);
    }
    return result.toString();
}

public String sortString(String s) {
    // Step 1: Pick the smallest character
    String sortedString = String.valueOf(s.charAt(0));

    // Step 2: Pick the smallest character greater than the last appended character
    int currentIndex = 1;
    while (currentIndex < s.length()) {
        char currentChar = s.charAt(currentIndex);
        if (currentChar > sortedString.charAt(sortedString.length() - 1)) {
            sortedString += currentChar;
            currentIndex++;
        } else {
            break;
        }
    }

    // Step 3: Repeat steps 1 and 2 until you cannot pick more characters
    while (currentIndex < s.length()) {
        char currentChar = s.charAt(currentIndex);
        if (currentChar <= sortedString.charAt(sortedString.length() - 1)) {
            sortedString = currentChar + sortedString;
            currentIndex++;
        } else {
            break;
        }
    }

    // Step 4: Pick the largest character
    int largestIndex = s.length() - 1;
    while (largestIndex >= 0) {
        char currentChar = s.charAt(largestIndex);
        if (currentChar < sortedString.charAt(0)) {
            sortedString = currentChar + sortedString;
            largestIndex--;
        } else {
            break;
        }
    }

    // Step 5: Pick the largest character smaller than the last appended character
    while (largestIndex >= 0) {
        char currentChar = s.charAt(largestIndex);
        if (currentChar >= sortedString.charAt(sortedString.length() - 1)) {
            sortedString += currentChar;
            largestIndex--;
        } else {
            break;
        }
    }

    // Step 6: Repeat steps 4 and 5 until you pick all characters from s
    while (largestIndex >= 0) {
        char currentChar = s.charAt(largestIndex);
        if (currentChar < sortedString.charAt(0)) {
            sortedString = currentChar + sortedString;
            largestIndex--;
        } else {
            break;
        }
    }

    return sortedString;
}

public static String sortString(String s) {
    if (s.isEmpty()) {
        return "";
    }
    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        // find the smallest character that is not in the result
        int smallest = Integer.MAX_VALUE;
        for (int i = 0; i < s.length(); i++) {
            if (!result.contains(s.charAt(i)) && s.charAt(i) < smallest) {
                smallest = s.charAt(i);
            }
        }
        // find the largest character that is not in the result
        int largest = Integer.MIN_VALUE;
        for (int i = 0; i < s.length(); i++) {
            if (!result.contains(s.charAt(i)) && s.charAt(i) > largest) {
                largest = s.charAt(i);
            }
        }
        // append the smallest and largest characters to the result
        result.append(smallest);
        result.append(largest);
    }
    return result.toString();
}

