    int i = 0;
    while (i < chars.length) {
        int min = chars[i];
        int max = chars[chars.length - 1];
        result.append((char) min);
        result.append((char) max);
        i++;
        while (i < chars.length && chars[i] < min) {
            result.append((char) chars[i]);
            i++;
        }
        while (i < chars.length && chars[i] > max) {
            result.append((char) chars[i]);
            i++;
        }
    }
    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    char[] temp = s.toCharArray();
    Arrays.sort(temp);
    StringBuilder result = new StringBuilder();
    while (result.length() < temp.length) {
        int smallestIndex = getSmallestIndex(temp, result.length());
        result.append(temp[smallestIndex]);
        temp[smallestIndex] = 0; // mark as visited

        int largestIndex = getLargestIndex(temp);
        result.append(temp[largestIndex]);
        temp[largestIndex] = 0; // mark as visited
    }
    return result.toString();
}

private int getSmallestIndex(char[] array, int startIndex) {
    int smallest = startIndex;
    for (int i = startIndex; i < array.length; i++) {
        if (array[i] < array[smallest]) {
            smallest = i;
        }
    }
    return smallest;
}

private int getLargestIndex(char[] array) {
    int largest = 0;
    for (int i = 0; i < array.length; i++) {
        if (array[i] > array[largest]) {
            largest = i;
        }
    }
    return largest;
}

public boolean splitArraySameAverage(int[] nums) {
