public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Initialize the minimum cost to reach the top with the first step
    int minCost = cost[0];

    // Iterate through the remaining steps
    for (int i = 1; i < cost.length; i++) {
        // Calculate the minimum cost to reach the top from the current step
        minCost = Math.min(minCost, cost[i] + minCostClimbingStairs(cost, i + 1));
    }

    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = Integer.MAX_VALUE;
    int currentCost = 0;
    for (int i = 0; i < cost.length; i++) {
        currentCost += cost[i];
        if (i == cost.length - 1) {
            minCost = Math.min(minCost, currentCost);
        } else {
            int nextCost = cost[i + 1];
            if (nextCost < currentCost) {
                minCost = Math.min(minCost, currentCost + nextCost);
            }
        }
    }
    return minCost;
}

