public int findMinFibonacciNumbers(int k) {
    int count = 0;
    int fib1 = 1;
    int fib2 = 1;
    int fib3 = 2;
    while (fib3 <= k) {
        if (fib3 == k) {
            count++;
            return count;
        } else if (fib3 < k) {
            int temp = fib2;
            fib2 = fib3;
            fib3 = fib1 + fib2;
            fib1 = temp;
            count++;
        } else {
            return -1;
        }
    }
    return -1;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 1) {
        return 1;
    }
    int[] fibonacciNumbers = new int[k];
    fibonacciNumbers[0] = 1;
    fibonacciNumbers[1] = 1;
    for (int i = 2; i < k; i++) {
        fibonacciNumbers[i] = fibonacciNumbers[i - 1] + fibonacciNumbers[i - 2];
    }
    int minFibonacciNumbers = Integer.MAX_VALUE;
    for (int i = 0; i < k; i++) {
        if (fibonacciNumbers[i] <= k) {
            int count = 1;
            while (fibonacciNumbers[i] + fibonacciNumbers[i + count] <= k) {
                count++;
            }
            minFibonacciNumbers = Math.min(minFibonacciNumbers, count);
        }
    }
    return minFibonacciNumbers;
}

