    List<Integer> fibNumbers = new ArrayList<>();

    // Generate the Fibonacci numbers until we reach the input value
    for (int i = 1; i <= k; i++) {
        // Calculate the next Fibonacci number
        int nextFib = fibNumbers.get(i - 1) + fibNumbers.get(i - 2);
        // Add the next Fibonacci number to the list
        fibNumbers.add(nextFib);
    }

    // Initialize a variable to store the minimum number of Fibonacci numbers
    int minFibNum = 1;

    // Loop through the Fibonacci numbers and find the minimum number of Fibonacci numbers that sum up to the input value
    for (int i = 0; i < fibNumbers.size(); i++) {
        // Check if the current Fibonacci number is greater than or equal to the input value
        if (fibNumbers.get(i) >= k) {
            // If it is, add 1 to the minimum number of Fibonacci numbers
            minFibNum++;
        } else {
            // If it's not, break out of the loop
            break;
        }
    }

    // Return the minimum number of Fibonacci numbers
    return minFibNum;
}

