public String makeGood(String s) {
    // Check if the input string is null or empty
    if (s == null || s.isEmpty()) {
        return s;
    }

    // Convert the input string to a character array
    char[] chars = s.toCharArray();

    // Loop through the character array and check for adjacent characters
    for (int i = 0; i < chars.length - 1; i++) {
        // If the current character is uppercase and the next character is its lowercase equivalent,
        // or if the current character is lowercase and the next character is its uppercase equivalent,
        // then remove both characters from the string
        if ((Character.isUpperCase(chars[i]) && Character.isLowerCase(chars[i + 1])) ||
                (Character.isLowerCase(chars[i]) && Character.isUpperCase(chars[i + 1]))) {
            chars = Arrays.copyOfRange(chars, 0, i - 1);
            chars = Arrays.copyOfRange(chars, i + 2, chars.length);
            i = i - 2;
        }
    }

    // Return the modified string
    return new String(chars);
}

public int maxUniqueSplit(String s) {
