    Set<String> uniqueSubstrings = new HashSet<>();

    // Initialize the maximum number of unique substrings
    int maxUniqueSubstrings = 0;

    // Loop through the characters in the string
    for (int i = 0; i < s.length(); i++) {
        // Get the current character
        char currentChar = s.charAt(i);

        // Check if the current character is already in the set
        if (!uniqueSubstrings.contains(currentChar)) {
            // If not, add it to the set
            uniqueSubstrings.add(currentChar);

            // Get the complement of the current substring
            String complement = s.substring(i + 1);

            // Check if the complement can be split into unique substrings
            int numUniqueSubstrings = maxUniqueSplit(complement);

            // If the complement can be split into unique substrings,
            // update the maximum number of unique substrings
            if (numUniqueSubstrings > maxUniqueSubstrings) {
                maxUniqueSubstrings = numUniqueSubstrings;
            }
        }
    }

    // Return the maximum number of unique substrings
    return maxUniqueSubstrings;
}

