public int minOperations(String[] logs) {
    // Handle edge case where the array is empty
    if (logs.length == 0) {
        return 0;
    }

    // Initialize a variable to keep track of the current directory
    String currentDirectory = "";

    // Iterate through the logs array
    for (String log : logs) {
        // Split the log into its components
        String[] logComponents = log.split("/");

        // Check if the log is a directory change
        if (logComponents.length > 1) {
            // Extract the new directory from the log
            String newDirectory = logComponents[1].trim();

            // Check if the new directory is a subdirectory of the current directory
            if (newDirectory.startsWith(currentDirectory)) {
                // Increment the number of operations by one
                currentDirectory = newDirectory;
            } else {
                // Check if the new directory is the parent directory of the current directory
                if (newDirectory.equals("..")) {
                    // Decrement the number of operations by one
                    currentDirectory = "";
                } else {
                    // Throw an exception if the new directory is not a subdirectory of the current directory
                    throw new IllegalArgumentException("Invalid folder path: " + log);
                }
            }
        } else {
            // If the log is not a directory change, it must be a file change
            if (logComponents[0].equals("./")) {
                // Count the number of files in the current directory
                int numFiles = currentDirectory.split("/").length;

                // Check if the number of files is greater than the number of folders
                if (numFiles > currentDirectory.split("/").length) {
                    // Throw an exception if the file count is greater than the folder count
                    throw new IllegalArgumentException("Invalid file count: " + log);
                }
            }
        }
    }

    // Return the number of operations required to return to the main folder
    return currentDirectory.split("/").length - 1;
}

public String getSmallestString(int n, int k) {
    if (n < 1 || k < 1) {
        throw new IllegalArgumentException("n and k must be positive integers");
    }
    if (n > 26) {
        throw new IllegalArgumentException("n must be less than or equal to 26");
    }
    if (k > (n * (n + 1)) / 2) {
        throw new IllegalArgumentException("k must be less than or equal to the sum of the first n positive integers");
    }
    String result = "";
    int i = 1;
    while (result.length() < n) {
        int currentValue = getLexicographicValue(result);
        if (currentValue < k) {
            result += "a";
        } else {
            result += "b";
        }
        i++;
    }
    return result;
}

private int getLexicographicValue(String str) {
    int value = 0;
    for (int i = 0; i < str.length(); i++) {
        value += (i + 1) * (str.charAt(i) - 'a' + 1);
    }
    return value;
}

public String getSmallestString(int n, int k) {
    if (n < 1 || k < 1) {
