    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        int charValue = (i % 2 == 0) ? 26 - (k - i) : (k - i);
        sb.append((char) ('a' + charValue));
    }
    return sb.toString();
}

public String getSmallestString(int n, int k) {
    if (n < 1 || k < 1) {
        throw new IllegalArgumentException("Invalid input");
    }
    if (n == 1) {
        return Character.toString(k);
    }
    StringBuilder result = new StringBuilder();
    int remaining = k - n;
    for (int i = 1; i <= n; i++) {
        int charValue = Math.min(remaining, 26);
        remaining -= charValue;
        result.append((char) (charValue - 1 + 'a'));
    }
    return result.toString();
}

public static String getSmallestString(int n, int k) {
   /**
     * Returns the lexicographically smallest string of length n and value k.
     */

   if (n <= 0 || k <= 0){
       throw new IllegalArgumentException("The input numbers must be postive.");
   }

   int[] values = new int[n];
   Arrays.fill(values, 0);
   values[0] = k;

   for (int i = 1; i < n; i++) {
       values[i] = (values[i - 1] % 26) + 1;
   }

   String result = "";

   for (int i = 0; i < n; i++) {
       result += (char) (values[i] - 1);
   }

   return result;
}

