                int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {-1, 1}};
                for (int[] direction : directions) {
                    int length = extendLine(mat, i, j, direction);
                    currentLength = Math.max(currentLength, length);
                }
                maxLength = Math.max(maxLength, currentLength);
            }
        }
    }
    return maxLength;
}

private static int extendLine(int[][] mat, int i, int j, int[] direction) {
    int length = 1;
    int x = i + direction[0];
    int y = j + direction[1];
    while (x >= 0 && x < mat.length && y >= 0 && y < mat[x].length && mat[x][y] == 1) {
        length++;
        x += direction[0];
        y += direction[1];
    }
    return length;
}

