public static int squarePermutations(int[] A) {
    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (A[i] < 0) {
            throw new IllegalArgumentException("The input array must be non-negative.");
        }
    }
    for (int i = 0; i < A.length - 1; i++) {
        int sum = A[i] + A[i + 1];
        if (isPerfectSquare(sum)) {
            count++;
        }
    }
    return count;
}

private static boolean isPerfectSquare(int x) {
    int sqrt = (int) Math.sqrt(x);
    return sqrt * sqrt == x;
}

public static int squarePermutations(int[] A) {
    Set<Integer> seen = new HashSet<>();
    int count = 0;
    int sum = 0;
    for (int i = 0; i < A.length; i++) {
        sum += A[i];
        if (sum == 0) {
            count++;
            seen.add(0);
        } else if (sum < 0) {
            continue;
        } else {
            int root = (int) Math.sqrt(sum);
            if (root * root == sum) {
                count++;
                seen.add(sum);
            }
        }
    }
    return count;
}

