}

public static int squarePermutations(int[] A) {
    // Check if the input array is valid
    if (A == null || A.length == 0) {
        throw new IllegalArgumentException("Invalid input array");
    }

    // Initialize the result
    int result = 0;

    // Iterate through each permutation of the input array
    for (int i = 0; i < A.length; i++) {
        // Get the current permutation
        int[] currentPermutation = getPermutation(A, i);

        // Check if the current permutation is a square array
        if (isSquareArray(currentPermutation)) {
            result++;
        }
    }

    return result;
}

private static int[] getPermutation(int[] A, int index) {
    // Get the current permutation
    int[] currentPermutation = new int[A.length];
    for (int i = 0; i < A.length; i++) {
        currentPermutation[i] = A[(index + i) % A.length];
    }
    return currentPermutation;
}

private static boolean isSquareArray(int[] A) {
    // Check if the array is empty
    if (A.length == 0) {
        return true;
    }

    // Check if the first element is a perfect square
    if (!isPerfectSquare(A[0])) {
        return false;
    }

    // Check if the sum of each pair of adjacent elements is a perfect square
    for (int i = 1; i < A.length; i++) {
        if (!isPerfectSquare(A[i] + A[i - 1])) {
            return false;
        }
    }

    return true;
}

private static boolean isPerfectSquare(int x) {
    // Check if the input is negative or zero
    if (x <= 0) {
        return false;
    }

    // Calculate the square root of the input
    int squareRoot = (int) Math.sqrt(x);

    // Check if the square root is an integer
    return squareRoot * squareRoot == x;
}

