  }

  String digits = String.valueOf(n);

  for (int i = digits.length() - 1; i > 0; i--) {
    for (int j = 0; j < i; j++) {
      if (digits.charAt(j) > digits.charAt(i)){
        char temp = digits.charAt(j);
        digits = digits.substring(0, j) + digits.charAt(i) + digits.substring(j + 1);
        digits = digits.substring(0, i + 1) + temp + digits.substring(i + 1);
      }
    }
  }

  return Integer.parseInt(digits);
}

