public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Calculate the slopes of the lines
    double slope1 = (double) (y2 - y1) / (x2 - x1);
    double slope2 = (double) (y3 - y2) / (x3 - x2);

    // Check if the slopes are the same
    if (slope1 == slope2) {
        return false;
    }

    // Check if the points are on the same line
    if (y1 - y2 == slope1 * (x1 - x2)) {
        return false;
    }

    // Check if the points are on the same line
    if (y2 - y3 == slope2 * (x2 - x3)) {
        return false;
    }

    // Check if the triange is a boomerang
    if (slope1 * (x3 - x1) == y3 - y1 && slope2 * (x3 - x2) == y3 - y2) {
        return true;
    }

    return false;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }
    int[][] sortedPoints = sortPoints(points);
    int[] v1 = subtractPoints(sortedPoints[1], sortedPoints[0]);
    int[] v2 = subtractPoints(sortedPoints[2], sortedPoints[1]);
    return dotProduct(v1, v2) == 0 && distance(sortedPoints[0], sortedPoints[1]) != distance(sortedPoints[1], sortedPoints[2]);
}

private static int[][] sortPoints(int[][] points) {
    int[][] sortedPoints = new int[points.length][2];
    for (int i = 0; i < points.length; i++) {
        sortedPoints[i] = points[i];
    }
    Arrays.sort(sortedPoints, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
    return sortedPoints;
}

private static int[] subtractPoints(int[] p1, int[] p2) {
    return new int[]{p1[0] - p2[0], p1[1] - p2[1]};
}

private static int dotProduct(int[] v1, int[] v2) {
    return v1[0] * v2[0] + v1[1] * v2[1];
}

private static int distance(int[] p1, int[] p2) {
    return (int) Math.sqrt(Math.pow(p1[0] - p2[0], 2) + Math.pow(p1[1] - p2[1], 2));
}

