}

public static boolean isBoomerang(int[][] points) {
    // Check if the array has exactly 3 points
    if (points.length != 3) {
        return false;
    }

    // Calculate the slope and y-intercept of the first line segment
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    double slope1 = (double) (y2 - y1) / (x2 - x1);
    double yIntercept1 = y1 - slope1 * x1;

    // Calculate the slope and y-intercept of the second line segment
    x2 = points[2][0];
    y2 = points[2][1];
    double slope2 = (double) (y2 - y1) / (x2 - x1);
    double yIntercept2 = y1 - slope2 * x1;

    // Check if the two line segments intersect
    if (slope1 == slope2 && yIntercept1 == yIntercept2) {
        return true;
    }

    // Check if the three points are collinear
    if (slope1 * (x2 - x1) == slope2 * (x2 - x1)) {
        return true;
    }

    // Check if the three points form a boomerang
    if (slope1 * (x2 - x1) == slope2 * (x1 - x2)) {
        return true;
    }

    // Check if the three points form a vertical line
    if (slope1 == Double.POSITIVE_INFINITY || slope2 == Double.POSITIVE_INFINITY) {
        return true;
    }

    // The points do not form a boomerang
    return false;
}

