            num /= 2;
        } else if (num % 3 == 0) {
            num /= 3;
        } else if (num % 5 == 0) {
            num /= 5;
        } else {
            return false;
        }
    }
    return true;
}

public static int findNthUglyNumber(int n) throws Exception {
    if (n < 1) {
        throw new Exception("Invalid input");
    }
    int count = 1;
    int current = 1;
    while (count < n) {
        current++;
        if (isUglyNumber(current)) {
            count++;
        }
    }
    return current;
}

private static boolean isUglyNumber(int num) {
    if (num <= 0) {
        return false;
    }
    while (num % 2 == 0) {
        num /= 2;
    }
    while (num % 3 == 0) {
        num /= 3;
    }
    while (num % 5 == 0) {
        num /= 5;
    }
    return num == 1;
}

public static int calculateEnergy(String s) {
        int max_len = 0;
        int[] char_count = new int[26]; // count of each character.
        char last_char = '?'; // last character seen.
        int last_char_count = 0; //count of last char seen.
        for (int i=0; i < s.length(); i++) {
            char curr_char = s.charAt(i);
            if (curr_char != last_char) {
                char_count[curr_char - 'a']++;
                if (last_char != '\0')
                    char_count[last_char - 'a'] = last_char_count;
                last_char = curr_char;
                last_char_count = 1;
            } else {
                last_char_count++;
            }
        }
        for (int i=0; i < 26; i++)
            if (char_count[i] > max_len)
                max_len = char_count[i];
        return max_len;
    }

public static int calculateEnergy(String s) throws IllegalArgumentException {
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Invalid input: the string must not be null or empty.");
    }
    int energy = 0;
    char currentChar = s.charAt(0);
    int currentStreak = 1;
    for (int i = 1; i < s.length(); i++) {
        char nextChar = s.charAt(i);
        if (nextChar == currentChar) {
            currentStreak++;
        } else {
            currentStreak = 1;
            currentChar = nextChar;
        }
        energy = Math.max(energy, currentStreak);
    }
    return energy;
}

