public static int minPerfectSquareSum(int n) {
    int minSquares = Integer.MAX_VALUE;
    for (int i = 1; i <= Math.sqrt(n); i++) {
        int count = minPerfectSquareSum(n - i * i);
        if (count < minSquares) {
            minSquares = count;
        }
    }
    return minSquares;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be greater than or equal to 1");
    }

    int[] squares = new int[n];
    for (int i = 1; i <= n; i++) {
        squares[i - 1] = i * i;
    }

    int min = Integer.MAX_VALUE;
    for (int i = 0; i < squares.length; i++) {
        int sum = 0;
        for (int j = i; j < squares.length; j++) {
            sum += squares[j];
            if (sum == n) {
                min = Math.min(min, j - i + 1);
                break;
            }
        }
    }

    return min;
}

public static int minPerfectSquareSum(int n) {
    // Find the perfect square numbers that sum up to n
    List<Integer> perfectSquares = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        int square = i * i;
        if (square <= n) {
            perfectSquares.add(square);
        } else {
            break;
        }
    }

    // Return the minimum number of perfect square numbers
    return perfectSquares.size();
}

public static int minPerfectSquareSum(int n) {
    int minSquares = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        if (root * root == n) {
            minSquares++;
            break;
        } else {
            minSquares++;
            n -= root * root;
        }
    }
    return minSquares;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be a non-negative integer");
    }
    int count = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        n -= root * root;
        count++;
    }
    return count;
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
      return s;
    }
    String[] words = s.split(" ");
    StringBuilder sb = new StringBuilder();
    for (String word : words) {
      sb.append(new StringBuilder(word).reverse().toString()).append(" ");
    }
    return sb.toString().trim();
}

